 private void xrPivotGrid1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
        {
            xrPivotGrid1.BestFit();
            xrPivotGrid1.CanGrow = true;
            xrPivotGrid1.CanShrink = true;

        }
 private void xrPivotGrid1_FieldValueDisplayText(object sender, DevExpress.XtraReports.UI.PivotGrid.PivotFieldDisplayTextEventArgs e)
        {

    		if (e.ValueType == DevExpress.XtraPivotGrid.PivotGridValueType.Total && e.IsColumn )
            {
                if (e.Value.ToString() != "% Rritje /Renie")
                {
                    e.DisplayText = "TOTALI " + e.Value.ToString().Substring(e.Value.ToString().Length - 4, 4);
                }
                else
                {
                    e.DisplayText = "TOTALE";
                }
            }
            if (e.ValueType == DevExpress.XtraPivotGrid.PivotGridValueType.GrandTotal && e.IsColumn==false)
            { 
                    e.DisplayText = "Totali Menaxheret ";

            }

        }

        private void xrPivotGrid1_CustomFieldSort(object sender, DevExpress.XtraReports.UI.PivotGrid.PivotGridCustomFieldSortEventArgs e)
        {
            if (e.Field.FieldName == "GRUPIMSHITJE")
            {
                object orderValue1 = e.GetListSourceColumnValue(e.ListSourceRowIndex1, "VITI"),
                orderValue2 = e.GetListSourceColumnValue(e.ListSourceRowIndex2, "VITI");

                int comparison = Comparer.Default.Compare(orderValue1, orderValue2);
                e.Result = comparison;
                e.Handled = true;
                return;

            }
        }

  private void xrPivotGrid1_CustomCellValue(object sender, DevExpress.XtraReports.UI.PivotGrid.PivotCellValueEventArgs e)
        {
            if (e.DataField.FieldName == "VLERA" && (e.RowValueType == DevExpress.XtraPivotGrid.PivotGridValueType.Total || e.ColumnValueType == DevExpress.XtraPivotGrid.PivotGridValueType.Total || e.RowValueType == DevExpress.XtraPivotGrid.PivotGridValueType.GrandTotal))
            {

                DevExpress.XtraPivotGrid.PivotDrillDownDataSource ds = e.CreateDrillDownDataSource();
                Double customValue = 0;
  		    Double v11 = 0;
                Double v12 = 0;
                Boolean s = false;
                for (int i = 0; i < ds.RowCount; i++)
                {
                    object currentType = ds.GetValue(i, "TIPI");
			  object v1 = ds.GetValue(i, "v1");
                    object v2 = ds.GetValue(i, "v2");	
                    if (currentType != null && Convert.ToInt32(currentType.ToString()) == 0)
                    {
                        customValue += Convert.ToDouble(ds.GetValue(i, "VLERA"));

                    }
                    else
                    {
                        v11 += Convert.ToDouble(ds.GetValue(i, "v1"));
                        v12 += Convert.ToDouble(ds.GetValue(i, "v2"));
                        s = true;

                    }
                }
                if (s==true)
                {
                   if (v12==0)
                     {
                        e.Value = 100; 
                     }
                	 else
                     	{
                      	  e.Value = String.Format("{0:n2}", ((v11 - v12) / v12)*100);
                    	}              
                }
                else
                {
                    e.Value = String.Format("{0:n2}", customValue);

                }
             }	

            else
            {
                if (e.Value == null || e.Value.ToString() == "")
                {
                    e.Value = 0;
                }
            }
        }
